"""Core scanning functionality for PropScan."""

import subprocess
import shutil
import json
import os
from typing import List, Dict, Optional, Set
from pathlib import Path


class PackageManager:
    """Base class for package managers."""

    def __init__(self, name: str, command: str):
        self.name = name
        self.command = command

    def is_available(self) -> bool:
        """Check if this package manager is available on the system."""
        return shutil.which(self.command) is not None

    def get_installed_packages(self) -> List[Dict[str, str]]:
        """Get list of installed packages. Override in subclasses."""
        raise NotImplementedError


class FlatpakManager(PackageManager):
    """Flatpak package manager."""

    def __init__(self):
        super().__init__("Flatpak", "flatpak")

    def get_installed_packages(self) -> List[Dict[str, str]]:
        """Get installed Flatpak applications."""
        try:
            result = subprocess.run(
                ["flatpak", "list", "--app", "--columns=application,name,version"],
                capture_output=True,
                text=True,
                check=True
            )

            packages = []
            for line in result.stdout.strip().split('\n')[1:]:  # Skip header
                if line.strip():
                    parts = line.split('\t')
                    if len(parts) >= 2:
                        packages.append({
                            "name": parts[0],
                            "display_name": parts[1] if len(parts) > 1 else parts[0],
                            "version": parts[2] if len(parts) > 2 else "unknown",
                            "manager": "flatpak"
                        })
            return packages
        except (subprocess.CalledProcessError, FileNotFoundError):
            return []


class PacmanManager(PackageManager):
    """Pacman package manager (Arch Linux)."""

    def __init__(self):
        super().__init__("Pacman", "pacman")

    def get_installed_packages(self) -> List[Dict[str, str]]:
        """Get installed Pacman packages."""
        try:
            result = subprocess.run(
                ["pacman", "-Q"],
                capture_output=True,
                text=True,
                check=True
            )

            packages = []
            for line in result.stdout.strip().split('\n'):
                if line.strip():
                    parts = line.split()
                    if len(parts) >= 2:
                        packages.append({
                            "name": parts[0],
                            "display_name": parts[0],
                            "version": parts[1],
                            "manager": "pacman"
                        })
            return packages
        except (subprocess.CalledProcessError, FileNotFoundError):
            return []


class AptManager(PackageManager):
    """APT package manager (Debian/Ubuntu)."""

    def __init__(self):
        super().__init__("APT", "apt")

    def get_installed_packages(self) -> List[Dict[str, str]]:
        """Get installed APT packages."""
        try:
            result = subprocess.run(
                ["dpkg", "-l"],
                capture_output=True,
                text=True,
                check=True
            )

            packages = []
            for line in result.stdout.strip().split('\n'):
                if line.startswith('ii'):  # Only installed packages
                    parts = line.split()
                    if len(parts) >= 3:
                        packages.append({
                            "name": parts[1],
                            "display_name": parts[1],
                            "version": parts[2],
                            "manager": "apt"
                        })
            return packages
        except (subprocess.CalledProcessError, FileNotFoundError):
            return []


class DnfManager(PackageManager):
    """DNF/YUM package manager (Fedora/RHEL)."""

    def __init__(self):
        super().__init__("DNF", "dnf")

    def get_installed_packages(self) -> List[Dict[str, str]]:
        """Get installed DNF packages."""
        try:
            # Try dnf first, fall back to yum
            cmd = "dnf" if shutil.which("dnf") else "yum"
            result = subprocess.run(
                [cmd, "list", "installed"],
                capture_output=True,
                text=True,
                check=True
            )

            packages = []
            in_packages = False
            for line in result.stdout.strip().split('\n'):
                if "Installed Packages" in line:
                    in_packages = True
                    continue

                if in_packages and line.strip():
                    parts = line.split()
                    if len(parts) >= 2:
                        name = parts[0].split('.')[0]  # Remove architecture
                        packages.append({
                            "name": name,
                            "display_name": name,
                            "version": parts[1],
                            "manager": "dnf"
                        })
            return packages
        except (subprocess.CalledProcessError, FileNotFoundError):
            return []


class ProprietaryDatabase:
    """Database of known proprietary software."""

    def __init__(self, data_file: Optional[str] = None):
        if data_file is None:
            # Default to bundled data file
            data_file = os.path.join(os.path.dirname(__file__), "data", "proprietary.json")

        self.proprietary_packages = self._load_database(data_file)

    def _load_database(self, data_file: str) -> Set[str]:
        """Load proprietary software database."""
        try:
            with open(data_file, 'r') as f:
                data = json.load(f)
                return set(data.get("proprietary_packages", []))
        except (FileNotFoundError, json.JSONDecodeError):
            # Return default set if file not found
            return self._get_default_proprietary_packages()

    def _get_default_proprietary_packages(self) -> Set[str]:
        """Default list of known proprietary software."""
        return {
            # Common proprietary software
            "google-chrome", "chrome", "google-chrome-stable",
            "discord", "com.discordapp.Discord",
            "spotify", "com.spotify.Client",
            "steam", "com.valvesoftware.Steam",
            "zoom", "us.zoom.Zoom",
            "slack", "com.slack.Slack",
            "skype", "com.skype.Client",
            "teamviewer", "com.teamviewer.TeamViewer",
            "dropbox", "com.dropbox.Client",
            "nvidia", "nvidia-driver", "nvidia-utils",
            "virtualbox", "virtualbox-host-modules",
            "vmware", "vmware-workstation",
            "opera", "com.opera.Opera",
            "vivaldi", "com.vivaldi.Vivaldi",
            "sublime-text", "com.sublimetext.three",
            "jetbrains-toolbox", "com.jetbrains.IntelliJ-IDEA-Ultimate",
            "adobe-flash-plugin", "flashplugin",
            "rar", "unrar",
            "microsoft-edge", "com.microsoft.Edge",
            "whatsapp", "com.whatsapp.WhatsApp",
            "telegram", "org.telegram.desktop",
            "obs-studio", "com.obsproject.Studio",
            "gimp", "org.gimp.GIMP",
            "blender", "org.blender.Blender",
        }

    def is_proprietary(self, package_name: str) -> bool:
        """Check if a package is proprietary."""
        # Check exact match and partial matches
        package_lower = package_name.lower()
        for prop_pkg in self.proprietary_packages:
            if prop_pkg.lower() in package_lower or package_lower in prop_pkg.lower():
                return True
        return False


class PropScan:
    """Main scanner class."""

    def __init__(self):
        self.managers = [
            FlatpakManager(),
            PacmanManager(),
            AptManager(),
            DnfManager(),
        ]
        self.db = ProprietaryDatabase()

    def get_available_managers(self) -> List[PackageManager]:
        """Get list of available package managers."""
        return [manager for manager in self.managers if manager.is_available()]

    def scan_manager(self, manager: PackageManager) -> List[Dict[str, str]]:
        """Scan a specific package manager for proprietary software."""
        packages = manager.get_installed_packages()
        proprietary = []

        for package in packages:
            if self.db.is_proprietary(package["name"]):
                proprietary.append(package)

        return proprietary

    def scan_all(self, manager_filter: Optional[str] = None) -> Dict[str, List[Dict[str, str]]]:
        """Scan all available package managers."""
        results = {}
        available_managers = self.get_available_managers()

        for manager in available_managers:
            if manager_filter and manager.name.lower() != manager_filter.lower():
                continue

            proprietary = self.scan_manager(manager)
            if proprietary:
                results[manager.name] = proprietary

        return results
